# ---------------- merge & validate ----------------
def main():
    d = json.load(open(PATH))
    seen_domains = {x['id'] for x in d['domains']}
    for dom in new_domains:
        assert dom['id'] not in seen_domains, f"duplicate domain {dom['id']}"
        d['domains'].append(dom)
    seen_lessons = {(x['domain_id'], x['title']) for x in d['lessons']}
    for les in new_lessons:
        assert (les['domain_id'], les['title']) not in seen_lessons, f"dup lesson {les['title']}"
        assert len(les['concepts']) >= 4 and len(les['pitfalls']) >= 3, f"thin lesson {les['title']}"
    d['lessons'].extend(new_lessons)
    seen_scen = {s['id'] for x in d['domains'] for s in x.get('scenarios', [])}
    for dom_id, scs in new_scenarios.items():
        tgt = next(x for x in d['domains'] if x['id'] == dom_id)
        for s in scs:
            assert s['id'] not in seen_scen, f"dup scenario {s['id']}"
            assert s['answer'] < len(s['choices']), f"bad answer idx {s['id']}"
            assert len(s['choices']) == 4, f"choices != 4 {s['id']}"
            assert all(len(ev) == 2 for ev in s['evidence']), f"evidence pair {s['id']}"
        tgt['scenarios'].extend(scs)
    seen_labs = {x['id'] for x in d['labs']}
    for lab in new_labs:
        assert lab['id'] not in seen_labs, f"dup lab {lab['id']}"
    d['labs'].extend(new_labs)
    with open(PATH, 'w') as f:
        json.dump(d, f, indent=2, ensure_ascii=False)
    d2 = json.load(open(PATH))
    print('domains:', len(d2['domains']))
    print('lessons:', len(d2['lessons']))
    print('scenarios:', sum(len(x.get('scenarios', [])) for x in d2['domains']))
    print('labs:', len(d2['labs']))

main()
